async function checkCameraPermission() {
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        // Если поток видео получен без ошибок, разрешение предоставлено
        return true;
    } catch (error) {
        // Обработка ошибок, например, если пользователь отклонил разрешение
        console.error('Ошибка при проверке разрешения на веб-камеру:', error);
        return false;
    } finally {
        // Закрытие потока после проверки
        if (stream) {
            stream.getTracks().forEach(track => track.stop());
        }
    }
}

// Функция для проверки настроек конфиденциальности веб-камеры
async function checkPrivacySettings() {
    const cameraSettings = await navigator.mediaDevices.getPermissions();
    const cameraPermission = cameraSettings.find(permission => permission.kind === 'camera');

    if (cameraPermission && cameraPermission.state === 'granted') {
        console.log('Доступ к веб-камере разрешен.');
    } else {
        console.log('Доступ к веб-камере запрещен. Пожалуйста, проверьте настройки конфиденциальности.');
    }
