import React, { useEffect, useState } from 'react';
import axios from 'axios';

const App = () => {
  const [isSiteAvailable, setIsSiteAvailable] = useState(false);

  useEffect(() => {
    const checkSiteAvailability = async () => {
      try {
        const response = await axios.get('https://your-website.com'); // Замените на ваш основной URL
        setIsSiteAvailable(true);
      } catch (error) {
        setIsSiteAvailable(false);
        window.location.href = '/maintenance.html'; // Перенаправление на страницу технического обслуживания
      }
    };

    checkSiteAvailability();
  }, []);

  if (!isSiteAvailable) {
    return <div>Сайт временно недоступен. Пожалуйста, попробуйте позже.</div>;
